findings.codeql_raw_query:
/**
 * @name SSRF via user-controlled URLs in httpx
 * @description User-controlled data flowing to URL construction could lead to SSRF attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf-httpx
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for URL construction in httpx
    exists(API::CallNode call |
      call = API::moduleImport("httpx").getMember(["Client", "AsyncClient"]).getMember(["get", "post", "put", "delete", "head", "patch", "request"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SSRFConfigFlow = TaintTracking::Global<SSRFConfig>;
import SSRFConfigFlow::PathGraph

from SSRFConfigFlow::PathNode source, SSRFConfigFlow::PathNode sink
where SSRFConfigFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability: user-controlled URL in httpx request from $@.", source.getNode(), "user input"
